select json_build_object('weeks',(select count(distinct tab_date) from billing_import),'min',(select min(tab_date) from billing_import),'max',(select max(tab_date) from billing_import),'goldie',(select json_agg(x) from (select tab_date,company,ref,coalesce(array_length(links,1),0) nl from billing_import where lower(regexp_replace(ref,'[^a-zA-Z0-9]','','g'))='ujo9583' order by tab_date desc limit 12) x)) r;
